import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation reused a shared {@link Parser} instance and
 * attempted to disable entity resolution inside a synchronized block.  This
 * approach was unsafe because the parser could be used by another thread
 * before the options were applied, leaving the application vulnerable to
 * XML External Entity (XXE) attacks.</p>
 *
 * <p>The patched version creates a fresh {@link Parser} for each request,
 * configures a dedicated {@link ParserOptions} object with entity resolution
 * explicitly disabled, and passes those options to the parser.  No mutable
 * static state is shared between threads, eliminating the race condition and
 * ensuring that the parser is always hardened against XXE.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  MessageBodyReader implementation (patched)
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Defensive check – a null InputStream would cause a NPE inside the parser.
        if (entityStream == null) {
            throw new IllegalArgumentException("InputStream cannot be null");
        }

        // Obtain a fresh parser instance for this call.  Abdera's getParser()
        // returns a new, thread‑local parser, which prevents cross‑thread state
        // leakage.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that are guaranteed to be applied before parsing.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Critical security setting – disable resolution of external entities.
        options.setResolveEntities(false);
        // Additional hardening (if supported by the version of Abdera):
        // options.setExpandEntities(false); // uncomment if the API provides it.

        // Parse the stream using the explicitly configured options.
        Document<T> doc = parser.parse(entityStream, options);

        // The document should always contain a root element; however, we guard
        // against a malformed/empty document to avoid returning null to callers.
        T root = doc.getRoot();
        if (root == null) {
            throw new IOException("Failed to parse Atom entry: no root element found");
        }
        return root;
    }

    // ----------------------------------------------------------------------
    //  Remaining abstract / concrete methods (unchanged)
    // ----------------------------------------------------------------------
    // other methods ...

}
