import org.apache.commons.lang3.StringUtils;
import java.util.logging.Logger;

/**
 * URLValidator – validates URL fields.
 *
 * The original implementation of {@code getUrlRegex()} could return a very
 * large regular‑expression when either {@code urlRegexExpression} or
 * {@code urlRegex} were {@code null}.  While functionally correct, this caused
 * unnecessary processing overhead and could be abused to trigger a denial‑of‑
 * service (DoS) condition.  The method has been hardened to:
 *
 * <ul>
 *   <li>Perform explicit {@code null} and whitespace checks.</li>
 *   <li>Trim values before evaluation.</li>
 *   <li>Gracefully handle parsing errors.</li>
 *   <li>Return a concise, well‑tested default pattern when no custom
 *       expression is supplied.</li>
 * </ul>
 *
 * The class remains compatible with Java 7.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    /** A safe, compact default URL regular expression. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[^\\s/$.?#].[^\\s]*$";

    private String urlRegex;
    private String urlRegexExpression;

    // other methods ...

    /**
     * Returns the regular expression used for client‑side URL validation.
     *
     * <p>The method now defensively checks for {@code null} and blank values,
     * trims the input, and catches any exception that may be thrown by the
     * {@code parse} operation.  If a custom expression cannot be used, a
     * predefined safe default pattern is returned.</p>
     *
     * @return a non‑null regular expression string.
     */
    public String getUrlRegex() {
        // 1. Prefer a user‑supplied expression (urlRegexExpression)
        if (urlRegexExpression != null) {
            String trimmedExpr = urlRegexExpression.trim();
            if (!trimmedExpr.isEmpty()) {
                try {
                    // parse may throw; we guard against it.
                    Object parsed = parse(trimmedExpr, String.class);
                    if (parsed instanceof String) {
                        return (String) parsed;
                    } else {
                        LOG.warning("Parsed urlRegexExpression is not a String; falling back to defaults.");
                    }
                } catch (Exception e) {
                    LOG.warning("Failed to parse urlRegexExpression: " + e.getMessage()
                            + " – falling back to defaults.");
                }
            }
        }

        // 2. Fallback to a directly supplied regex (urlRegex)
        if (urlRegex != null) {
            String trimmedUrlRegex = urlRegex.trim();
            if (!trimmedUrlRegex.isEmpty()) {
                return trimmedUrlRegex;
            }
        }

        // 3. Final fallback – a concise, safe default pattern.
        return DEFAULT_URL_REGEX;
    }

    // other methods ...

}
