public static File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir is null");
    if (name == null) throw new IllegalArgumentException("name is null");
    // remove query part
    int q = name.indexOf('?');
    if (q >= 0) {
        name = name.substring(0, q);
    }
    // Extract only the file name component (no directories)
    // Use Paths to get file name
    java.nio.file.Path namePath = java.nio.file.Paths.get(name).getFileName();
    if (namePath == null) {
        throw new IllegalArgumentException("Invalid file name");
    }
    String safeName = namePath.toString();

    // Optionally reject any remaining path traversal characters like ".."
    if (safeName.contains("..")) {
        throw new IllegalArgumentException("File name contains prohibited path traversal sequence");
    }

    // Build file
    java.io.File file = new java.io.File(dir, safeName);
    // Ensure canonical path is within dir
    try {
        java.io.File canonicalDir = dir.getCanonicalFile();
        java.io.File canonicalFile = file.getCanonicalFile();
        if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + java.io.File.separator)) {
            // If same as dir (maybe file name empty) also reject
            if (!canonicalFile.equals(canonicalDir)) {
                throw new IllegalArgumentException("Resulting file is outside the target directory");
            }
        }
    } catch (java.io.IOException e) {
        throw new RuntimeException("Failed to resolve file paths", e);
    }

    // Determine prefix/suffix for duplicate handling
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = new java.io.File(dir, newName);
        // re-validate canonical path each iteration
        try {
            java.io.File canonicalFile = file.getCanonicalFile();
            java.io.File canonicalDir = dir.getCanonicalFile();
            if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + java.io.File.separator) &&
                !canonicalFile.equals(canonicalDir)) {
                throw new IllegalArgumentException("Resulting file is outside the target directory");
            }
        } catch (java.io.IOException e) {
            throw new RuntimeException("Failed to resolve file paths", e);
        }
    }

    // Ensure parent directories exist
    java.io.File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}

