    // Other utility methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Allocates a {@link File} inside {@code dir} using the supplied {@code name}.
     * <p>
     * The method performs the following security‑focused steps:
     * <ul>
     *   <li>Strips any URL‑style query component (everything after a {@code '?'}).</li>
     *   <li>Extracts only the final path element, discarding any directory components
     *       that may contain {@code ".."} or separator characters.</li>
     *   <li>Ensures the resulting canonical path is a descendant of {@code dir}.</li>
     *   <li>If a file with the same name already exists, appends a numeric suffix
     *       (e.g. {@code -2}) while preserving the same safety guarantees.</li>
     *   <li>Creates missing parent directories in a safe manner.</li>
     * </ul>
     *
     * @param dir  the target directory (must exist or be creatable)
     * @param name the requested file name; may originate from untrusted sources
     * @return a {@link File} object that safely points inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if the resolved path would escape {@code dir}
     * @throws IllegalStateException    if required directories cannot be created
     */
    public static File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // -------------------------------------------------------------------
        // 1. Remove any query string (e.g. "file.txt?foo=bar")
        // -------------------------------------------------------------------
        int q = name.indexOf('?');
        if (q >= 0) {
            name = name.substring(0, q);
        }

        // -------------------------------------------------------------------
        // 2. Keep only the last path element – this discards any directory
        //    components supplied by the caller (including "..").
        // -------------------------------------------------------------------
        Path extracted = Paths.get(name).getFileName();
        if (extracted == null) {
            throw new IllegalArgumentException("Invalid file name: " + name);
        }
        String safeName = extracted.toString();

        // Defensive check: reject any remaining traversal sequences.
        if (safeName.contains("..")) {
            throw new IllegalArgumentException("File name contains prohibited path traversal sequence");
        }

        // -------------------------------------------------------------------
        // 3. Build the initial File object and verify it stays inside 'dir'.
        // -------------------------------------------------------------------
        File file = new File(dir, safeName);
        ensurePathInsideBase(dir, file);

        // -------------------------------------------------------------------
        // 4. Resolve naming collisions while preserving the safety checks.
        // -------------------------------------------------------------------
        int dot = safeName.lastIndexOf('.');
        String prefix = (dot < 0) ? safeName : safeName.substring(0, dot);
        String suffix = (dot < 0) ? "" : safeName.substring(dot);
        int index = 2;

        while (file.exists()) {
            String candidateName = prefix + "-" + index++ + suffix;
            file = new File(dir, candidateName);
            ensurePathInsideBase(dir, file);
        }

        // -------------------------------------------------------------------
        // 5. Create missing parent directories atomically.
        // -------------------------------------------------------------------
        File parent = file.getParentFile();
        if (parent != null && !parent.isDirectory()) {
            if (!parent.mkdirs() && !parent.isDirectory()) {
                throw new IllegalStateException("Failed to create directories for: " + parent.getAbsolutePath());
            }
        }

        return file;
    }

    /**
     * Verifies that {@code target} resolves to a canonical path that is a
     * descendant of {@code base}. Throws {@link IllegalArgumentException} if the
     * check fails.
     */
    private static void ensurePathInsideBase(File base, File target) {
        try {
            File canonicalBase = base.getCanonicalFile();
            File canonicalTarget = target.getCanonicalFile();

            String basePath = canonicalBase.getPath();
            String targetPath = canonicalTarget.getPath();

            // Normalise with a trailing separator to avoid false positives where
