import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.logging.Logger;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>This implementation avoids using externally supplied seed material,
 * which could be predictable and weaken the randomness. The {@code SecureRandom}
 * instance is always seeded using the JVM's built‑in secure seeding mechanism.
 *
 * <p>If a seed {@link Resource} is configured, it is ignored and a warning is logged.
 * This preserves backward compatibility (the property can still be set) while
 * eliminating the security risk.
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private static final Logger logger = Logger.getLogger(SecureRandomFactoryBean.class.getName());

    /** Default algorithm – kept for compatibility; can be overridden. */
    private String algorithm = "SHA1PRNG";

    /** Optional seed resource – retained for API compatibility but not used. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        // -------------------------------------------------------------------
        // 1. Create the SecureRandom instance using the configured algorithm.
        //    If the algorithm is null/empty we fall back to the default
        //    constructor which selects the strongest provider available.
        // -------------------------------------------------------------------
        SecureRandom rnd;
        if (algorithm != null && !algorithm.trim().isEmpty()) {
            try {
                rnd = SecureRandom.getInstance(algorithm);
            } catch (NoSuchAlgorithmException ex) {
                // Propagate a clear message – the caller supplied an invalid algorithm.
                throw new IllegalArgumentException(
                        "SecureRandom algorithm '" + algorithm + "' is not available.", ex);
            }
        } else {
            rnd = new SecureRandom(); // uses platform‑default strong algorithm
        }

        // -------------------------------------------------------------------
        // 2. Explicitly trigger internal seeding. The call to nextBytes forces
        //    the provider to obtain entropy from the OS if it hasn't already.
        // -------------------------------------------------------------------
        rnd.nextBytes(new byte[1]);

        // -------------------------------------------------------------------
        // 3. If a seed resource was supplied, log a warning and ignore it.
        //    Using external seed data can make the RNG predictable.
        // -------------------------------------------------------------------
        if (seed != null) {
            logger.warning("A seed resource was configured for SecureRandomFactoryBean, "
                    + "but it is ignored to avoid weakening randomness.");
        }

        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // Each call returns a freshly seeded SecureRandom; not a singleton.
        return false;
    }

    // -----------------------------------------------------------------------
    // Property setters (used by Spring configuration)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }
}
