import java.util.HashMap;

/**
 * Header delegate for {@code MediaType}. The implementation validates the
 * {@code type} and {@code subtype} components of a media type according to
 * RFC 7230 token rules. Only characters that are explicitly allowed in a token
 * are accepted; all others (including control characters, whitespace,
