 */
public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // -----------------------------------------------------------------------
    // Token validation (RFC 7230, Section 3.2.6)
    // -----------------------------------------------------------------------
    // Allowed characters for a token:  ! # $ % & ' * + - . ^ _ ` | ~
    //                                 DIGIT (0‑9) and ALPHA (A‑Z, a‑z)
    // All other ASCII characters, control characters, whitespace, and any
    // non‑ASCII characters are disallowed.
    private static final boolean[] VALID_TOKEN = new boolean[128];

    static {
        // Populate the whitelist of allowed token characters.
        String allowed = "!#$%&'*+-.^_`|~"
                + "0123456789"
                + "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                + "abcdefghijklmnopqrstuvwxyz";
        for (char c : allowed.toCharArray()) {
            VALID_TOKEN[c] = true;
        }
    }

    /**
     * Validates that the supplied string conforms to the token definition
     * required for media type {@code type} and {@code subtype} components.
     *
     * @param str the string to validate
     * @return {@code true} if the string consists solely of allowed token
     *         characters and is non‑null/non‑empty; {@code false} otherwise.
     */
    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            // Disallow any character outside the 7‑bit ASCII range.
            if (c >= VALID_TOKEN.length) {
                return false;
            }
            // Disallow characters not present in the whitelist.
            if (!VALID_TOKEN[c]) {
