private static void decompress(InputStream in, byte[] out) throws IOException {
    int position = 0;
    final int total = out.length;
    while (position < total) {
        int n = in.read();
        if (n == -1) {
            throw new IOException("Unexpected end of stream while decompressing");
        }
        if (n == 0) {
            throw new IOException("Invalid run length 0 in compressed data");
        }
        if (n > 128) {
            int repeatCount = n & 0x7f;
            int value = in.read();
            if (value == -1) {
                throw new IOException("Unexpected end of stream while reading repeat value");
            }
            if (repeatCount > total - position) {
                throw new IOException("Run exceeds output buffer size");
            }
            for (int i = 0; i < repeatCount; i++) {
                out[position++] = (byte) value;
            }
        } else {
            int literalCount = n;
            if (literalCount > total - position) {
                throw new IOException("Literal run exceeds output buffer size");
            }
            for (int i = 0; i < literalCount; i++) {
                int b = in.read();
                if (b == -1) {
                    throw new IOException("Unexpected end of stream while reading literal bytes");
                }
                out[position++] = (byte) b;
            }
        }
    }
}

