private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path targetPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);
    ArchiveEntry entry;
    while ((entry = supplier.getNextReadableEntry()) != null) {
        String entryName = entry.getName();
        if (entryName == null) {
            continue; // or throw
        }
        // Reject absolute paths explicitly
        if (new File(entryName).isAbsolute()) {
            throw new IOException("Entry name is absolute: " + entryName);
        }
        Path resolvedPath = targetPath.resolve(entryName).normalize();
        if (!resolvedPath.startsWith(targetPath)) {
            throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
        }
        if (entry.isDirectory()) {
            Files.createDirectories(resolvedPath);
        } else {
            Path parent = resolvedPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                writer.writeEntryDataTo(entry, out);
            }
        }
    }
}

