public class Expander {

    // other methods

    /**
     * Expands archive entries into {@code targetDirectory} while protecting against
     * path‑traversal attacks.
     *
     * <p>The method resolves each entry name against the canonical (real) path of the
     * target directory, normalises the result and verifies that the resulting path
     * is still within the target directory.  Absolute entry names are rejected
     * explicitly.  All directory creation uses {@link Files#createDirectories(Path)}
     * which safely creates the required hierarchy.</p>
     *
     * @param supplier        supplies the next readable {@link ArchiveEntry}
     * @param writer          writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which entries are expanded
     * @throws IOException if an I/O error occurs or a security check fails
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        Path targetPath = targetDirectory.toPath()
                                         .toRealPath(LinkOption.NOFOLLOW_LINKS);

        ArchiveEntry entry;
        while ((entry = supplier.getNextReadableEntry()) != null) {
            String entryName = entry.getName();

            if (entryName == null) {
                // Skip entries without a name – they cannot be written safely.
                continue;
            }

            // Reject absolute paths outright; resolve would otherwise ignore the targetPath.
            if (new File(entryName).isAbsolute()) {
                throw new IOException("Entry name is absolute and therefore unsafe: " + entryName);
            }

            // Resolve the entry against the target directory and normalise the result.
            Path resolvedPath = targetPath.resolve(entryName).normalize();

            // Ensure the resolved path is still inside the target directory.
            if (!resolvedPath.startsWith(targetPath)) {
                throw new IOException("expanding " + entryName
                        + " would create file outside of " + targetDirectory);
            }

            if (entry.isDirectory()) {
                // Create the directory (and any missing parents) safely.
                Files.createDirectories(resolvedPath);
            } else {
                // Ensure the parent directory exists.
                Path parent = resolvedPath.getParent();
                if (parent != null) {
                    Files.createDirectories(parent);
                }

                // Write the entry data to the resolved file.
                try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                    writer.writeEntryDataTo(entry, out);
                }
            }
        }
    }

    // other methods

}
