import static java.util.Calendar.*;

public final class CronTab {

    // other methods

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar and set a hard limit two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // A generous but finite bound prevents an infinite loop (DoS). The bound is far larger than any
        // realistic number of adjustments required for a valid cron expression.
        final int MAX_ITERATIONS = 1_000;

        // The outer loop is now bounded. The label allows us to restart the whole adjustment
        // process when a field modification may affect higher‑order fields.
        ITERATION:
        for (int iteration = 0; iteration < MAX_ITERATIONS; iteration++) {

            // If we have already moved beyond the two‑year safety window, the date is considered
            // too rare or impossible.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // Walk through the fields in the defined adjustment order.
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);          // current value of the field
                int next = f.ceil(this, cur);      // next acceptable value according to the cron rules

                // No change required for this field – move on.
                if (cur == next) {
                    continue;
                }

                // A higher‑order field is about to change; clear all lower‑order fields
                // to keep the date consistent.
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                // If the field has no valid value (next < 0) we need to roll it up
                // and start the whole adjustment process again.
                if (next < 0) {
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    // Restart the outer iteration – a higher field may now be out of range.
                    continue ITERATION;
                } else {
                    // Set the field to the next valid value.
                    f.setTo(cal, next);

                    // Some fields (e.g., day‑of‑month) may require a full re‑evaluation after
                    // being modified because the change can affect other fields.
                    if (f.redoAdjustmentIfModified) {
                        continue ITERATION;
                    }
                }
            }

            // All fields are now valid and no restart was requested – we have a correct date.
            return cal;
        }

        // If we exit the bounded loop we assume the expression is too rare/complex.
        throw new RareOrImpossibleDateException(
                "Exceeded maximum adjustment iterations while computing next execution time");
    }

    // other methods

}
