     * @param toVersion   the end version, must not be {@code null}
     * @return a negative integer, zero, or a positive integer as
     *         {@code fromVersion} is less than, equal to, or greater than
     *         {@code toVersion}
     * @throws IllegalArgumentException if either argument is {@code null},
     *                                  does not contain exactly three components,
     *                                  or contains non‑numeric components
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings must not be null");
        }

        int[] from = parseVersion(fromVersion);
        int[] to   = parseVersion(toVersion);

        // Compare major, then minor, then patch numbers.
        for (int i = 0; i < 3; i++) {
            int diff = from[i] - to[i];
            if (diff != 0) {
                return diff;
            }
        }
        return 0; // versions are equal
    }

