     *
     * @param version the version string to parse
     * @return an int array of length 3 containing the numeric components
     * @throws IllegalArgumentException if the format is invalid or a component
     *                                  cannot be parsed as an integer
     */
    private static int[] parseVersion(String version) {
        // Trim whitespace to avoid accidental parsing errors.
        String[] parts = version.trim().split("\\.");
        if (parts.length != 3) {
            throw new IllegalArgumentException(
                "Version must consist of three numeric components separated by '.' : " + version);
        }

        int[] numbers = new int[3];
        for (int i = 0; i < 3; i++) {
            try {
                numbers[i] = Integer.parseInt(parts[i]);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException(
                    "Non‑numeric version component in '" + version + "': '" + parts[i] + "'", e);
            }
        }
        return numbers;
