    /**
     * Determines whether the currently authenticated user is allowed to perform a self‑update
     * on the {@link ScimUser} identified by the request URL.
     *
     * <p>The method now enforces strict ownership checks:
     * <ul>
     *   <li>The request must be made by an authenticated principal.</li>
     *   <li>The authenticated principal's user ID must match the user ID extracted from the URL.</li>
     *   <li>All mutable fields (email, username, verification flag, active flag, origin) are compared
     *       using {@link Objects#equals(Object, Object)} to safely handle {@code null}s.</li>
     * </ul>
     *
     * @param request the incoming HTTP request containing the JSON payload
     * @return {@code true} if the update is a legitimate self‑update; {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // ---- 1. Verify authentication and ownership ----
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication == null || !authentication.isAuthenticated()) {
            // No authenticated user – deny the operation
            return false;
        }

        String authenticatedUserId = null;
        Object principal = authentication.getPrincipal();

        if (principal instanceof UaaUser) {
            authenticatedUserId = ((UaaUser) principal).getId();
        } else if (principal instanceof String) {
            // In some configurations the principal may be the user ID string directly
            authenticatedUserId = (String) principal;
        }

        if (authenticatedUserId == null) {
            // Unable to determine the caller's identity – deny
            return false;
        }

        // Extract the target user ID from the request URL
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        // The caller must be updating their own record
        if (!Objects.equals(authenticatedUserId, targetUserId)) {
            return false;
        }

        // ---- 2. Parse request payload safely ----
        String requestBody = IOUtils.toString(request.getReader());
        if (requestBody == null || requestBody.trim().isEmpty()) {
            // Empty payload – nothing to compare, deny as a precaution
            return false;
        }

        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        // ---- 3. Retrieve the persisted user record ----
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot allow an update – treat as not allowed
            return false;
        }

        // ---- 4. Compare immutable fields to ensure only self‑updates ----
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the request is a legitimate self‑update
        return true;
    }

